mapper.select:
SELECT *
FROM base_address
WHERE dong_code = #{dongCode};

SELECT gugun_code, gugun_name
FROM gugun_code
JOIN sido_code
ON SUBSTRING(gugun_code, 1, 2) = SUBSTRING(sido_code, 1, 2)
WHERE sido_code = #{sidoCode}
ORDER BY gugun_name;

SELECT dong_code, dong_name
FROM dong_code AS dc
JOIN gugun_code AS gc
ON dc.gugun_name = gc.gugun_name
WHERE gugun_code = #{gugunCode}
ORDER BY dong_name;

SELECT COUNT(DISTINCT apt_code)
FROM house_info
WHERE SUBSTRING(dong_code, 1, 5) = SUBSTRING(#{gugunCode}, 1, 5);

SELECT COUNT(DISTINCT apt_code)
FROM house_info
WHERE dong_code = #{dongCode};

SELECT COUNT(DISTINCT apt_code)
FROM house_info
WHERE apt_name LIKE CONCAT('%', #{keyword}, '%');

SELECT COUNT(DISTINCT apt_code)
FROM house_info
WHERE dong_code = #{dongCode}
    AND apt_name LIKE CONCAT('%', #{keyword}, '%');

SELECT hd.no, hi.apt_code, hi.apt_name, hi.dong_code, hd.area, hd.floor, hi.lat, hi.lng, hd.deal_year, hd.deal_month, hd.deal_day, hd.deal_amount
FROM house_deal hd, house_info hi
WHERE hd.apt_code = hi.apt_code
    AND hd.apt_code = #{aptCode}
ORDER BY hd.no DESC;

SELECT count(*)
FROM house_deal
WHERE apt_code = #{aptCode};
